// Illustrated card faces: extracted from the Claude Design canvas "獵巫鎮卡牌設計" (Illustrated.dc.html); do not edit by hand
// Each SVG viewBox is 0 0 200 160; gradient/filter ids carry a per-card prefix so they do not collide
import type { CardType, TryalKind } from '@salem/engine';

export interface CardArt {
  name: string;
  /** Short line printed on the card */
  text: string;
  /** Frame base color and triangle pattern */
  bg: string;
  pattern: string;
  /** Illustration border color */
  border: string;
  /** Name band background */
  band: string;
  /** Text color */
  ink: string;
  /** Illustration description (accessible name) */
  label: string;
  /** Accusation points on red cards (number of filled dots); null for other cards */
  pips: number | null;
  /** Footer line (non-red cards: 用完棄掉 / 留在面前 / 抽到立即發動 / 審判牌) */
  footer: string;
  /** Inner SVG content (without the outer <svg>) */
  svg: string;
}

